<script setup lang="ts">
import { computed, nextTick, onBeforeUnmount, onMounted, ref } from 'vue'
import { message } from 'ant-design-vue'
import { ChevronDown, Folder, Maximize2, Minimize2, Minus, Plus, Server, TerminalSquare, X } from 'lucide-vue-next'
import { useAuthStore } from '@/stores/auth'
import { useHostTerminalsStore } from '@/stores/hostTerminals'
import TerminalSessionPane from '@/components/TerminalSessionPane.vue'
import TerminalFileBrowser from '@/components/TerminalFileBrowser.vue'

const store = useHostTerminalsStore(), auth = useAuthStore()
const showFiles = ref(true), enlarged = ref(false), mobile = ref(false), groupMenu = ref('')
const menuLeft = ref(8)
const panes = new Map<string, { focus: () => Promise<void> }>(), files = new Map<string, { confirmDiscard: () => Promise<boolean> }>()
const canFiles = computed(() => Boolean(auth.user) && auth.canAny(['terminal.file.read', 'terminal.file.upload']))
const labels = { connecting: '连接中', connected: '已连接', closed: '已结束', error: '连接失败' }
function setPane(id: string, pane: unknown) { if (pane) panes.set(id, pane as { focus: () => Promise<void> }); else panes.delete(id) }
function setFiles(id: string, pane: unknown) { if (pane) files.set(id, pane as { confirmDiscard: () => Promise<boolean> }); else files.delete(id) }
async function activate(id: string) { groupMenu.value = ''; store.activate(id); await nextTick(); if (!mobile.value || !showFiles.value || !canFiles.value) void panes.get(id)?.focus() }
async function minimize() { store.minimize(); groupMenu.value = ''; await nextTick(); document.getElementById(`terminal-group-${store.active?.hostId}`)?.focus({ preventScroll: true }) }
async function close(id: string) { if (await files.get(id)?.confirmDiscard() === false) return; store.close(id) }
function newSession() { if (!store.active) return; const result = store.duplicate(store.active.id); if (result.error) message.warning(result.error) }
function toggleGroup(id: string, event: MouseEvent) { menuLeft.value = Math.max(8, Math.min((event.currentTarget as HTMLElement).getBoundingClientRect().left - 140, window.innerWidth - 288)); groupMenu.value = groupMenu.value === id ? '' : id }
function resize() { mobile.value = window.innerWidth <= 700 }
function contextChanged() { groupMenu.value = ''; store.syncContext() }
function keyboard(event: KeyboardEvent) { if (event.key === 'Escape' && groupMenu.value) { groupMenu.value = ''; event.stopPropagation() } }
onMounted(() => { resize(); window.addEventListener('resize', resize); window.addEventListener('storage', contextChanged); window.addEventListener('edo:projects-changed', contextChanged) })
onBeforeUnmount(() => { store.clear(); window.removeEventListener('resize', resize); window.removeEventListener('storage', contextChanged); window.removeEventListener('edo:projects-changed', contextChanged) })
</script>

<template>
  <Teleport to="body">
    <div v-if="store.sessions.length" class="terminal-dock" :class="{ expanded: enlarged }" @keydown="keyboard">
      <section v-show="!store.minimized" class="terminal-dock-window" role="dialog" aria-modal="false" aria-label="主机终端工作区">
        <header class="dock-header" role="presentation"><TerminalSquare :size="18" aria-hidden="true" /><strong>{{ store.active?.hostName }}</strong><span class="dock-connection" :class="store.active?.state" role="status"><i />{{ store.active ? labels[store.active.state] : '' }}</span><span class="dock-spacer" /><button v-if="canFiles" type="button" :aria-pressed="showFiles" title="文件" aria-label="切换文件面板" @click="showFiles = !showFiles"><Folder :size="16" /></button><button type="button" title="新建同主机终端" aria-label="新建同主机终端" :disabled="store.sessions.length >= 8" @click="newSession"><Plus :size="18" /></button><button v-if="!mobile" type="button" :title="enlarged ? '还原窗口' : '扩大窗口'" :aria-label="enlarged ? '还原窗口' : '扩大窗口'" @click="enlarged = !enlarged"><Minimize2 v-if="enlarged" :size="16" /><Maximize2 v-else :size="16" /></button><button type="button" title="最小化" aria-label="最小化主机终端" @click="minimize"><Minus :size="19" /></button><button type="button" title="关闭当前会话" aria-label="关闭当前终端会话" @click="store.active && close(store.active.id)"><X :size="18" /></button></header>
        <nav class="dock-session-tabs" aria-label="主机终端会话"><div v-for="(session, index) in store.sessions.filter(item => item.hostId === store.active?.hostId)" :key="session.id" class="dock-session-tab" :class="{ active: session.id === store.activeId }"><button type="button" :aria-pressed="session.id === store.activeId" @click="activate(session.id)"><TerminalSquare :size="13" aria-hidden="true" />终端 {{ index + 1 }}<span class="session-state" :class="session.state">{{ labels[session.state] }}</span></button><button type="button" :aria-label="`关闭 ${session.hostName} 终端 ${index + 1}`" @click="close(session.id)"><X :size="13" /></button></div></nav>
        <div class="dock-session-body">
          <div v-for="session in store.sessions" v-show="session.id === store.activeId" :key="session.id" class="dock-session" :class="{ 'files-shown': showFiles && canFiles }">
            <TerminalFileBrowser v-if="canFiles" v-show="showFiles" :ref="value => setFiles(session.id, value)" :path="session.path" />
            <div v-show="!mobile || !showFiles || !canFiles" class="dock-console"><TerminalSessionPane :ref="value => setPane(session.id, value)" :path="session.path" permission="host.terminal.open" :visible="!store.minimized && store.activeId === session.id && (!mobile || !showFiles || !canFiles)" @state="store.updateState(session.id, $event)" /></div>
            <button v-if="mobile && showFiles && canFiles" class="mobile-terminal-toggle" type="button" @click="showFiles = false"><TerminalSquare :size="16" />返回终端</button>
          </div>
        </div>
      </section>
      <nav class="terminal-program-bar" aria-label="主机终端程序栏">
        <span class="program-bar-brand"><TerminalSquare :size="16" aria-hidden="true" /><span>终端</span></span>
        <div class="program-groups"><div v-for="group in store.groups" :key="group.id" class="program-group">
          <button :id="`terminal-group-${group.id}`" type="button" class="program-group-main" :class="{ active: !store.minimized && store.active?.hostId === group.id }" :aria-label="`恢复 ${group.name} 的终端`" @click="activate(group.sessions.find(item => item.id === store.activeId)?.id ?? group.sessions[0]!.id)"><Server :size="15" aria-hidden="true" /><span>{{ group.name }}</span><small>{{ group.sessions.length }}</small></button>
          <button type="button" class="program-group-menu" :aria-label="`${group.name} 的终端会话列表`" :aria-expanded="groupMenu === group.id" @click="toggleGroup(group.id, $event)"><ChevronDown :size="14" /></button>
          <div v-if="groupMenu === group.id" class="program-session-menu" :style="{ left: `${menuLeft}px` }"><div v-for="(session, index) in group.sessions" :key="session.id"><button type="button" @click="activate(session.id)"><TerminalSquare :size="14" /><span>终端 {{ index + 1 }}</span><small>{{ labels[session.state] }}</small></button><button type="button" :aria-label="`关闭 ${group.name} 终端 ${index + 1}`" @click="close(session.id)"><X :size="14" /></button></div></div>
        </div></div>
        <button type="button" class="program-minimize" :aria-label="store.minimized ? '恢复主机终端' : '最小化主机终端'" @click="store.minimized ? activate(store.activeId) : minimize()"><TerminalSquare v-if="store.minimized" :size="17" /><Minus v-else :size="17" /></button>
      </nav>
    </div>
  </Teleport>
</template>

<style scoped>
.terminal-dock{position:fixed;left:0;right:0;bottom:0;z-index:980;color:var(--edo-text);font-size:13px;--dock-bar-height:calc(42px + env(safe-area-inset-bottom,0px))}.terminal-dock-window{position:absolute;left:16px;right:16px;bottom:var(--dock-bar-height);height:min(66vh,760px);min-height:280px;display:flex;flex-direction:column;border:1px solid var(--edo-border);border-radius:7px 7px 0 0;background:var(--edo-surface);box-shadow:0 -8px 30px #07101826;overflow:hidden}.terminal-dock.expanded .terminal-dock-window{height:calc(100dvh - var(--dock-bar-height) - 16px)}.dock-header{display:flex;align-items:center;gap:9px;min-height:43px;flex-shrink:0;padding:5px 10px 5px 14px;background:var(--edo-surface);border-bottom:1px solid var(--edo-border)}.dock-header>svg{color:var(--edo-primary);flex-shrink:0}.dock-header>strong{max-width:min(350px,40vw);font-size:13px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.dock-spacer{flex:1}.terminal-dock button{display:inline-flex;align-items:center;justify-content:center;gap:6px;min-width:30px;min-height:30px;padding:4px 6px;border:0;border-radius:4px;background:transparent;color:var(--edo-text);font:inherit;cursor:pointer}.terminal-dock button:hover:not(:disabled){background:var(--edo-primary-soft);color:var(--edo-primary)}.terminal-dock button:disabled{opacity:.45;cursor:not-allowed}.terminal-dock button:focus-visible{outline:2px solid var(--edo-primary);outline-offset:-2px}.dock-header button[aria-pressed="true"]{background:var(--edo-primary-soft);color:var(--edo-primary)}.dock-connection{display:flex;align-items:center;gap:5px;color:var(--edo-muted);font-size:11px;white-space:nowrap}.dock-connection i{width:6px;height:6px;border-radius:50%;background:var(--edo-muted)}.dock-connection.connected i{background:var(--edo-success,#23a675)}.dock-connection.error i{background:var(--edo-error,#d33f57)}.dock-session-tabs{display:flex;min-height:35px;flex-shrink:0;overflow-x:auto;background:var(--edo-surface-soft);border-bottom:1px solid var(--edo-border);padding:0 8px;gap:4px}.dock-session-tab{display:flex;align-items:center;border-bottom:2px solid transparent}.dock-session-tab.active{border-bottom-color:var(--edo-primary);background:var(--edo-surface)}.dock-session-tab>button{white-space:nowrap;font-size:12px}.session-state{font-size:10px;color:var(--edo-muted)}.dock-session-body{min-height:0;flex:1;position:relative}.dock-session{position:absolute;inset:0;display:flex;min-width:0}.dock-console{flex:1;min-width:0;min-height:0}.terminal-program-bar{display:flex;align-items:center;height:var(--dock-bar-height);padding:4px 10px calc(4px + env(safe-area-inset-bottom,0px));gap:8px;border-top:1px solid var(--edo-border);background:var(--edo-surface);box-shadow:0 -1px 5px #00000008}.program-bar-brand{display:inline-flex;align-items:center;gap:7px;padding:0 10px;color:var(--edo-muted);font-size:12px;flex-shrink:0}.program-groups{display:flex;align-items:center;gap:5px;flex:1;min-width:0;overflow-x:auto;overflow-y:visible;scrollbar-width:thin}.program-group{display:flex;flex-shrink:0;max-width:260px;border:1px solid var(--edo-border);border-radius:4px;background:var(--edo-surface-soft)}.program-group-main{min-width:0!important;max-width:220px;font-size:12px!important}.program-group-main>span{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.program-group-main svg{flex-shrink:0;color:var(--edo-primary)}.program-group-main small{min-width:18px;padding:0 3px;border-radius:3px;background:var(--edo-primary-soft);color:var(--edo-primary);font-size:11px}.program-group-main.active{box-shadow:inset 0 -2px var(--edo-primary);color:var(--edo-primary)}.program-group-menu{border-left:1px solid var(--edo-border)!important;border-radius:0 3px 3px 0!important;min-width:25px!important;padding:3px!important}.program-session-menu{position:fixed;bottom:calc(var(--dock-bar-height) + 4px);width:min(280px,90vw);padding:5px;background:var(--edo-surface);border:1px solid var(--edo-border);border-radius:5px;box-shadow:0 -4px 18px #0002;z-index:1}.program-session-menu>div{display:flex;align-items:center}.program-session-menu>div>button:first-child{flex:1;justify-content:flex-start;min-width:0;font-size:12px}.program-session-menu small{margin-left:auto;color:var(--edo-muted);font-size:11px}.program-minimize{flex-shrink:0}.mobile-terminal-toggle{position:absolute;bottom:12px;right:12px;background:var(--edo-surface)!important;border:1px solid var(--edo-border)!important;box-shadow:0 3px 12px #0002}@media(max-width:700px){.terminal-dock-window{left:0;right:0;height:76dvh;border-radius:0}.dock-header{gap:6px;padding:6px}.dock-header>strong{max-width:34vw}.dock-header button{min-width:34px;min-height:34px}.dock-session-tabs{min-height:38px}.dock-session-tab>button{min-height:35px}.terminal-program-bar{padding-inline:4px;gap:3px}.program-bar-brand{padding:0 4px}.program-bar-brand>span{display:none}.program-group-main{max-width:180px}.program-groups{gap:4px}}@media(prefers-reduced-motion:reduce){.terminal-dock *{scroll-behavior:auto!important}}
.terminal-dock{--terminal-link:#3859cc}.terminal-dock button:hover:not(:disabled),.terminal-dock .program-group-main.active,.terminal-dock .program-group-main small,.terminal-dock .dock-header button[aria-pressed="true"]{color:var(--terminal-link)}:global([data-theme="dark"] .terminal-dock){--terminal-link:#a5b7ff}
:global(html:has(.terminal-program-bar)){scroll-padding-bottom:calc(50px + env(safe-area-inset-bottom,0px))}
:global(body:has(.terminal-program-bar) .vben-content){padding-bottom:calc(60px + env(safe-area-inset-bottom,0px))}
:global(body:has(.terminal-program-bar) .vben-content :is(button,a,input,select,textarea,[tabindex])){scroll-margin-bottom:calc(50px + env(safe-area-inset-bottom,0px))}
@media(max-width:700px){:global(body:has(.terminal-program-bar) .vben-content){padding-bottom:calc(54px + env(safe-area-inset-bottom,0px))}}
</style>
